1	import React, { useCallback, useMemo } from "react";
2	import styled from "styled-components";
3	
4	import { useTranslation } from "react-i18next";
5	import { useParams } from "react-router-dom";
6	import type { Address } from "viem";
7	
8	import { Button } from "@kleros/ui-components-library";
9	
10	import { useRevealVote } from "hooks/useRevealVote";
11	import type { Bytes32Hash } from "utils/crypto/hashVote";
12	
13	import { useDisputeDetailsQuery } from "queries/useDisputeDetailsQuery";
14	import { usePopulatedDisputeData } from "queries/usePopulatedDisputeData";
15	
16	import { DisputeKits } from "src/dispute-kits";
17	
18	const Container = styled.div`
19	  width: 100%;
20	  height: auto;
21	  display: flex;
22	  justify-content: center;
23	  margin-top: 16px;
24	`;
25	
26	interface IReveal {
27	  arbitrable?: Address;
28	  commit?: Bytes32Hash;
29	  voteIDs: string[];
30	  setIsOpen: (val: boolean) => void;
31	  disputeKitId: DisputeKits;
32	}
33	
34	const Reveal: React.FC<IReveal> = ({ voteIDs, setIsOpen, disputeKitId, commit, arbitrable }) => {
35	  const { t } = useTranslation();
36	  const { id } = useParams();
37	  const { data: disputeData } = useDisputeDetailsQuery(id);
38	  const { data: disputeDetails } = usePopulatedDisputeData(id, arbitrable);
39	  const currentRoundIndex = disputeData?.dispute?.currentRoundIndex;
40	
41	  const parsedDisputeID = useMemo(() => BigInt(id ?? 0), [id]);
42	  const parsedVoteIDs = useMemo(() => voteIDs.map((voteID) => BigInt(voteID)), [voteIDs]);
43	
44	  const { mutateAsync: revealVote, isPending } = useRevealVote(() => {
45	    setIsOpen(true);
46	  });
47	  const handleReveal = useCallback(async () => {
48	    // inline check: src/utils cannot be loaded by vitest (@kleros/kleros-app has no main entry)
49	    if (currentRoundIndex === undefined || currentRoundIndex === null) {
50	      return;
51	    }
52	
53	    await revealVote({
54	      params: {
55	        disputeId: parsedDisputeID,
56	        voteIds: parsedVoteIDs,
57	        roundIndex: Number(currentRoundIndex),
58	        disputeKitId,
59	      },
60	      context: {
61	        commit,
62	        answers: disputeDetails?.answers,
